    "reserve_MW": 5934.9
  },
  "most_loaded_lines": [
    {"from": 1101, "to": 400, "loading_pct": 100.0},
    {"from": 91, "to": 200, "loading_pct": 100.0},
    {"from": 1660, "to": 2664, "loading_pct": 100.0}
